import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useLocation, Navigate } from 'react-router-dom';
import Login from './component/Login';
import Signup from './component/Signup';
import HomePage from './component/HomePage';
import AdminPage from './component/AdminPage';
import AdminLogin from './component/AdminLogin'; 
import './App.css';

function App() {
  const [user, setUser] = useState(() => {
    const email = localStorage.getItem('userEmail');
    const role = localStorage.getItem('userRole');
    const username = localStorage.getItem('username');
    if ((email || username) && role) {
      return { email, username, role };
    }
    return null;
  });

  const handleLogin = (userData) => {
    setUser(userData);
    if (userData.email) localStorage.setItem('userEmail', userData.email);
    if (userData.username) localStorage.setItem('username', userData.username);
    localStorage.setItem('userRole', userData.role);
  };

  return (
    <Router>
      <MainRoutes user={user} handleLogin={handleLogin} />
    </Router>
  );
}

function MainRoutes({ user, handleLogin }) {
  const location = useLocation();

  return (
    <>
      <Routes>
        {/* Public pages */}
        <Route path="/" element={<Login onLogin={handleLogin} />} />
        <Route path="/signup" element={<Signup />} />

        {/* User's main page (HomePage) */}
        <Route path="/home" element={
          user?.role === 'user' ? <HomePage user={user} /> : <Navigate to="/" replace />
        } />

        {/* Admin login and admin page */}
        <Route path="/admin-login" element={<AdminLogin onLogin={handleLogin} />} />
        <Route path="/admin" element={
          user?.role === 'admin' ? <AdminPage /> : <Navigate to="/admin-login" replace />
        } />
      </Routes>

      {/* Show nav only on public pages */}
      {!['/admin', '/home'].includes(location.pathname) && (
        <nav className="nav-bar">
          <Link to="/">User Login</Link>
          <span className="separator">|</span>
          <Link to="/signup">Signup</Link>
          <span className="separator">|</span>
          <Link to="/admin-login">Admin Login</Link>
        </nav>
      )}
    </>
  );
}

export default App;
